INSERT INTO feature VALUES('signature-translation','modules','An import read through a flow or a renaming','package-signature','implemented','notable',NULL,'`flow f : A ~~> B { … }` defines the members of the theory `B` over those of the theory `A`, its body reading `A`''s sorts and members by name, and `import <address> : S via f ;` reads its source through it. The source answers `A` as a source answers a signature, refused `SignatureMismatch` at the flow''s name, and `B` answers `S` by name and derived type, refused at the signature. The flow is the one declared before the import or published `pub` by the source; any other name refuses every declaration of the importer `NotATranslation`. A member defined as an `A` member''s name alone binds the source''s own declaration, adding no constant. `import <address> : S renaming { a as b, … } ;` reads its source through the flow that names each listed member `a` as `b` and every other member as itself, each pair refused `SignatureMismatch` where the source exports no `a` and `DuplicateDefinition` where another member holds `b`. `module M = f(N) ;` applies a flow to a module as a functor applies, and `M` exports a renamed member as `N`''s own. `path p : A <~> B { into { … } from { … } }` writes a flow each way: `p.into` and `p.from` are functions between packed models, and each sort and value member of each signature has a round trip, `Path.here(s.m)` at `p.from(p.into(s)).m`, that conversion decides over the bound model, refused `EndpointMismatch` at the member the way back defines.','surface-grammar surface-lowering','corpus/model/modules/translated.gandr corpus/pathological/modules/translated.gandr corpus/pathological/modules/translated-uncovered.gandr corpus/pathological/modules/round-trip.gandr corpus/ledger/diagnostics/NotATranslation.gandr crates/surface-lowering/tests/namespace.rs::an_import_via_a_flow_reads_its_source_through_it_3378 crates/surface-lowering/tests/namespace.rs::a_via_reads_a_flow_declared_before_it_or_published_by_its_source_3378 crates/surface-lowering/tests/namespace.rs::a_translation_is_refused_at_its_domain_or_its_codomain_3378 crates/surface-lowering/tests/namespace.rs::an_import_renaming_reads_its_source_s_member_under_the_signature_s_name_3461 crates/surface-lowering/tests/modules/functors.rs::a_flow_reads_its_domain_s_members_by_name crates/surface-lowering/tests/modules/functors.rs::a_flow_reads_its_domain_s_sorts_by_name_3461 crates/surface-lowering/tests/modules/functors.rs::a_flow_applies_to_a_module_3461 crates/surface-lowering/tests/modules/functors.rs::a_flow_from_no_theory_is_refused_under_its_name crates/surface-lowering/tests/modules/paths.rs::a_path_lowers_to_its_functions_and_its_round_trips_3487 crates/surface-lowering/tests/modules/paths.rs::a_path_that_moves_a_sort_states_its_round_trip_3487','corpus/model/modules/translated.gandr',NULL);
